// observerFunc is called after each routing decision to update stateful scorer state.
// Used by scorers like prefix-affinity that track routing history.
type observerFunc func(req *Request, targetInstance string)

// WeightedScoring routes requests using a composable scorer pipeline.
//
// Each scorer evaluates all instances on a [0,1] scale. Scores are combined
// with configurable weights: composite = Σ clamp(s_i) × w_i, then argmax.
//
// Available scorers: prefix-affinity (proportional prefix match ratio),
// queue-depth (min-max normalization of EffectiveLoad),
// kv-utilization (1 - KVUtilization), load-balance (1/(1 + EffectiveLoad)).
// See sim/routing_scorers.go and sim/routing_prefix_scorer.go for implementations.
//
// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	scores := make(map[string]float64, len(snapshots))

	// Compute load statistics across cluster
	maxLoad := 0
	minLoad := 999999
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad {
			maxLoad = el
		}
		if el < minLoad {
			minLoad = el
		}
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots)+1)

	// Dual-signal pressure: spread imbalance + absolute congestion
	loadSpread := maxLoad - minLoad
	spreadPressure := 0.0
	if maxLoad > 1 {
		spreadPressure = float64(loadSpread) / float64(maxLoad+1)
	}
	absPressure := avgLoad / (avgLoad + 2.0)
	loadPressure := spreadPressure*0.6 + absPressure*0.4

	// Session affinity boost for multi-turn conversations
	sessionBoost := 0.0
	if req.SessionID != "" {
		sessionBoost = 0.28
	}

	// Dynamic weights: shift toward load-balance under pressure
	dynWeights := make([]float64, len(ws.weights))
	copy(dynWeights, ws.weights)
	if len(dynWeights) >= 2 {
		prefixW := ws.weights[0]*(1.0-0.75*loadPressure) + sessionBoost
		loadW := ws.weights[1] * (1.0 + 1.8*loadPressure)
		wSum := prefixW + loadW
		if wSum > 0.001 {
			dynWeights[0] = prefixW / wSum
			dynWeights[1] = loadW / wSum
		}
	}

	// Base scoring with dynamic weights
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * dynWeights[i]
		}
	}

	// Post-scoring adjustments using instance signals
	inputLen := len(req.InputTokens)
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		fEl := float64(el)

		// Quadratic load penalty - strong for tail latency
		if el > 0 {
			penalty := 1.0 / (1.0 + 0.18*fEl*fEl)
			scores[snap.ID] *= (0.3 + 0.7*penalty)
		}

		// Hard cutoff: heavily penalize instances far above average
		if fEl > avgLoad+2.0 && avgLoad > 0.5 {
			excess := (fEl - avgLoad) / (avgLoad + 1.0)
			scores[snap.ID] *= 0.12 / (0.12 + excess)
		}

		// Queue depth penalty (queued requests wait longest)
		if snap.QueueDepth > 1 {
			qPenalty := 1.0 / (1.0 + 0.28*float64(snap.QueueDepth))
			scores[snap.ID] *= (0.45 + 0.55*qPenalty)
		}

		// Cache hit rate bonus (stronger for larger inputs)
		cacheW := 0.20
		if inputLen > 256 {
			cacheW = 0.32
		}
		scores[snap.ID] *= (1.0 - cacheW + cacheW*snap.CacheHitRate)

		// KV pressure penalty - graduated, starts at 0.68
		if snap.KVUtilization > 0.68 {
			kvP := (snap.KVUtilization - 0.68) / 0.32
			scores[snap.ID] *= (1.0 - 0.55*kvP*kvP)
		}

		// Large input: prefer instances with more free memory
		if inputLen > 220 && snap.FreeKVBlocks > 0 {
			memBonus := float64(snap.FreeKVBlocks) / float64(snap.FreeKVBlocks+180)
			scores[snap.ID] *= (1.0 + 0.13*memBonus)
		}

		// Floor to avoid zeroing
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	// Argmax selection
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
		snapshots[bestIdx].ID,
		fmt.Sprintf("weighted-scoring (score=%.3f)", bestScore),
		scores,
	)
}

